# Freedom Cheteni: publications, talks, projects and code, compiled 2026-11-05 as source material for a planned book,
# "Raising Humans in the Age of AI" by Esther Wojcicki and Freedom Cheteni.
# Summaries are written for this archive; no source text is reproduced.
# role: author | repost (another outlet's story shared on Cheteni's page) | speaker | producer (own channel) |
#       founder | editor | subject (written about Cheteni) | code
# status: opened (page or video data read) | listed (title and date from a listing or archive only)
# woj: 1 when Esther Wojcicki is named in the title, description or a substantial part of the text.
# ai: 1 when artificial intelligence or robots are a real subject.
C = []
def c(date, role, typ, title, venue, url, status, summary, note="", topics="", woj=0, ai=0):
    C.append(dict(date=date, role=role, type=typ, title=title, venue=venue, url=url, status=status,
                  summary=summary, note=note, topics=[t for t in topics.split(",") if t], woj=woj, ai=ai))
M = "https://medium.com/"
YT = "https://www.youtube.com/watch?v="
def rp(orig):
    return "Shared on Cheteni's Medium page. Medium says it first appeared at " + orig + ", and the text is that outlet's story, sometimes with a Woj Way title or added captions."

